//! Which application opens a given media type.
//!
//! Two file formats feed this, and the distinction between them is the
//! whole point:
//!
//! * **`mimeapps.list`** -- the *user's* choices. Highest priority, found in
//!   `$XDG_CONFIG_HOME/mimeapps.list` and the config dirs. Has three groups:
//!   `[Default Applications]` (an explicit "always open this with that"),
//!   `[Added Associations]`, and `[Removed Associations]` (a blocklist).
//! * **`mimeinfo.cache`** -- generated by `update-desktop-database` from the
//!   `MimeType=` keys of installed `.desktop` files. This is "what *can*
//!   open it", not "what *should*".
//!
//! Real examples from this machine:
//!
//! ```text
//! # ~/.config/mimeapps.list
//! [Default Applications]
//! application/pdf=org.gnome.Evince.desktop
//!
//! # /usr/share/applications/mimeinfo.cache
//! [MIME Cache]
//! application/pdf=com.google.Chrome.desktop;firefox.desktop;google-chrome.desktop;
//! ```
//!
//! Note the same type resolves differently depending on which file you ask,
//! which is exactly why precedence has to be explicit rather than emergent
//! from file-read order.
//!
//! This module maps *type → desktop file id*. Turning that id into a
//! runnable command is `crates/launcher`'s job -- keeping the two apart is
//! what stops this crate from depending on the launcher (see Cargo.toml).

use crate::mime_type::MimeType;
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;

/// A `.desktop` file's id -- its basename, e.g. `firefox.desktop`.
///
/// A newtype so it can't be confused with a display name or a path: the
/// association files speak exclusively in these ids, and resolving one to
/// an actual file is a separate lookup.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct DesktopId(String);

impl DesktopId {
    /// Wrap a raw id, rejecting anything that isn't a `.desktop` basename.
    ///
    /// Guards against a malformed line injecting a path -- these ids are
    /// later joined against application directories, so a `../..` would be
    /// a genuine escape.
    #[must_use]
    pub fn parse(raw: &str) -> Option<Self> {
        let trimmed = raw.trim();
        if trimmed.is_empty()
            || !trimmed.ends_with(".desktop")
            || trimmed.contains('/')
            || trimmed.contains("..")
        {
            return None;
        }
        Some(Self(trimmed.to_owned()))
    }

    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for DesktopId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

/// Which group of an association file a line belongs to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Group {
    Default,
    Added,
    Removed,
    /// `[MIME Cache]` from `mimeinfo.cache`.
    Cache,
    /// A group we don't care about.
    Other,
}

impl Group {
    fn parse(header: &str) -> Self {
        match header {
            "Default Applications" => Self::Default,
            "Added Associations" => Self::Added,
            "Removed Associations" => Self::Removed,
            "MIME Cache" => Self::Cache,
            _ => Self::Other,
        }
    }
}

/// The type→application association database.
#[derive(Debug, Clone, Default)]
pub struct Associations {
    /// Explicit user defaults, in preference order.
    defaults: HashMap<String, Vec<DesktopId>>,
    /// Everything else that claims to handle a type.
    candidates: HashMap<String, Vec<DesktopId>>,
    /// Explicitly blocked (type, app) pairs.
    removed: HashSet<(String, DesktopId)>,
}

impl Associations {
    /// Load the system association files in precedence order.
    #[must_use]
    pub fn load() -> Self {
        let mut assoc = Self::default();

        // Config dirs first: the user's explicit choices outrank anything
        // generated from installed packages.
        for path in Self::mimeapps_paths() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                assoc.merge_str(&text);
            }
        }
        for path in Self::mimeinfo_cache_paths() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                assoc.merge_str(&text);
            }
        }
        assoc
    }

    /// `mimeapps.list` locations, highest priority first.
    #[must_use]
    pub fn mimeapps_paths() -> Vec<PathBuf> {
        let mut paths = Vec::new();
        let config_home = std::env::var("XDG_CONFIG_HOME").unwrap_or_else(|_| {
            let home = std::env::var("HOME").unwrap_or_default();
            format!("{home}/.config")
        });
        paths.push(PathBuf::from(&config_home).join("mimeapps.list"));

        let config_dirs =
            std::env::var("XDG_CONFIG_DIRS").unwrap_or_else(|_| "/etc/xdg".to_owned());
        for dir in config_dirs.split(':').filter(|d| !d.is_empty()) {
            paths.push(PathBuf::from(dir).join("mimeapps.list"));
        }
        // The spec also allows one alongside the applications directories.
        for dir in Self::data_dirs() {
            paths.push(dir.join("applications/mimeapps.list"));
        }
        paths
    }

    /// `mimeinfo.cache` locations.
    #[must_use]
    pub fn mimeinfo_cache_paths() -> Vec<PathBuf> {
        Self::data_dirs()
            .into_iter()
            .map(|d| d.join("applications/mimeinfo.cache"))
            .collect()
    }

    /// XDG data dirs, highest priority first -- same resolution
    /// `crates/launcher` uses for `.desktop` discovery.
    fn data_dirs() -> Vec<PathBuf> {
        let mut dirs = Vec::new();
        let data_home = std::env::var("XDG_DATA_HOME").unwrap_or_else(|_| {
            let home = std::env::var("HOME").unwrap_or_default();
            format!("{home}/.local/share")
        });
        dirs.push(PathBuf::from(data_home));
        let data_dirs = std::env::var("XDG_DATA_DIRS")
            .unwrap_or_else(|_| "/usr/local/share:/usr/share".to_owned());
        for dir in data_dirs.split(':').filter(|d| !d.is_empty()) {
            dirs.push(PathBuf::from(dir));
        }
        dirs
    }

    /// Build from a single document's text.
    #[must_use]
    pub fn from_str_data(text: &str) -> Self {
        let mut assoc = Self::default();
        assoc.merge_str(text);
        assoc
    }

    /// Parse a `mimeapps.list`/`mimeinfo.cache` document into this database.
    ///
    /// Earlier sources win: a later file never overrides an association an
    /// earlier one already established, which is what makes
    /// [`Self::load`]'s ordering meaningful.
    pub fn merge_str(&mut self, text: &str) {
        let mut group = Group::Other;

        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if let Some(header) = line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
                group = Group::parse(header);
                continue;
            }
            if group == Group::Other {
                continue;
            }
            let Some((raw_mime, raw_apps)) = line.split_once('=') else {
                continue;
            };
            // Keep the key as a normalised string. We don't require it to
            // parse as a MimeType, because these files legitimately contain
            // pseudo-types like `x-scheme-handler/https` -- which are
            // well-formed anyway, but the tolerance costs nothing.
            let mime = raw_mime.trim().to_lowercase();
            if mime.is_empty() {
                continue;
            }

            // Values are `;`-separated with a trailing `;`.
            let ids: Vec<DesktopId> = raw_apps.split(';').filter_map(DesktopId::parse).collect();

            match group {
                Group::Default => Self::extend_unique(&mut self.defaults, &mime, ids),
                Group::Added | Group::Cache => {
                    Self::extend_unique(&mut self.candidates, &mime, ids);
                }
                Group::Removed => {
                    for id in ids {
                        self.removed.insert((mime.clone(), id));
                    }
                }
                Group::Other => {}
            }
        }
    }

    /// Append ids that aren't already present, preserving first-seen order.
    ///
    /// Order *is* preference, so a duplicate must not promote an entry that
    /// a higher-priority file already ranked lower.
    fn extend_unique(map: &mut HashMap<String, Vec<DesktopId>>, mime: &str, ids: Vec<DesktopId>) {
        let slot = map.entry(mime.to_owned()).or_default();
        for id in ids {
            if !slot.contains(&id) {
                slot.push(id);
            }
        }
    }

    /// The preferred application for `mime`, or `None` if nothing handles it.
    #[must_use]
    pub fn default_for(&self, mime: &MimeType) -> Option<DesktopId> {
        self.candidates_for(mime).into_iter().next()
    }

    /// Every application that can open `mime`, best first.
    ///
    /// User defaults lead, then everything else, with blocked pairs removed.
    /// This is the list an "Open With…" menu renders.
    #[must_use]
    pub fn candidates_for(&self, mime: &MimeType) -> Vec<DesktopId> {
        let key = mime.as_str();
        let mut out: Vec<DesktopId> = Vec::new();

        for id in self
            .defaults
            .get(key)
            .into_iter()
            .chain(self.candidates.get(key))
            .flatten()
        {
            if !self.removed.contains(&(key.to_owned(), id.clone())) && !out.contains(id) {
                out.push(id.clone());
            }
        }
        out
    }

    /// Whether any association at all is known.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.defaults.is_empty() && self.candidates.is_empty()
    }

    /// The directories `.desktop` files live in, highest priority first.
    ///
    /// Public because a caller that resolves *many* ids (a file browser
    /// building an "Open With" list) wants to compute this once rather than
    /// re-reading the environment per lookup, and because it is the honest
    /// seam for pointing a test at fixture directories.
    #[must_use]
    pub fn application_dirs() -> Vec<PathBuf> {
        Self::data_dirs()
            .into_iter()
            .map(|d| d.join("applications"))
            .collect()
    }

    /// Resolve a [`DesktopId`] to a file on disk, searching the standard
    /// application directories in priority order.
    #[must_use]
    pub fn resolve_path(id: &DesktopId) -> Option<PathBuf> {
        Self::resolve_path_in(id, &Self::application_dirs())
    }

    /// Resolve against explicit roots -- the seam tests use.
    #[must_use]
    pub fn resolve_path_in(id: &DesktopId, roots: &[PathBuf]) -> Option<PathBuf> {
        roots
            .iter()
            .map(|d| d.join(id.as_str()))
            .find(|p| p.is_file())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn mime(s: &str) -> MimeType {
        MimeType::parse(s).expect("valid mime")
    }

    const USER_CHOICES: &str = "\
[Default Applications]
application/pdf=org.gnome.Evince.desktop
text/html=helium.desktop
";

    const SYSTEM_CACHE: &str = "\
[MIME Cache]
application/pdf=com.google.Chrome.desktop;firefox.desktop;
text/html=firefox.desktop;
image/png=eog.desktop;
";

    #[test]
    fn parses_desktop_ids_and_rejects_bad_ones() {
        assert_eq!(
            DesktopId::parse("firefox.desktop").map(|d| d.to_string()),
            Some("firefox.desktop".to_owned())
        );
        // The trailing `;` in these files produces an empty final field.
        assert!(DesktopId::parse("").is_none());
        assert!(DesktopId::parse("firefox").is_none());
        // Path traversal must not survive -- ids get joined onto directories.
        assert!(DesktopId::parse("../../etc/passwd.desktop").is_none());
        assert!(DesktopId::parse("/abs/path.desktop").is_none());
    }

    #[test]
    fn reads_default_applications() {
        let a = Associations::from_str_data(USER_CHOICES);
        assert_eq!(
            a.default_for(&mime("application/pdf"))
                .map(|d| d.to_string()),
            Some("org.gnome.Evince.desktop".to_owned())
        );
    }

    #[test]
    fn reads_the_mime_cache_group() {
        let a = Associations::from_str_data(SYSTEM_CACHE);
        assert_eq!(
            a.default_for(&mime("image/png")).map(|d| d.to_string()),
            Some("eog.desktop".to_owned())
        );
    }

    /// The core precedence rule, using the exact conflict present on this
    /// machine: the user picked Evince, the system cache lists Chrome and
    /// Firefox. Evince must win.
    #[test]
    fn user_default_outranks_system_cache() {
        let mut a = Associations::from_str_data(USER_CHOICES);
        a.merge_str(SYSTEM_CACHE);

        assert_eq!(
            a.default_for(&mime("application/pdf"))
                .map(|d| d.to_string()),
            Some("org.gnome.Evince.desktop".to_owned()),
            "the user's explicit choice must beat the generated cache"
        );
    }

    /// …but the cache's entries still appear, below the default, so an
    /// "Open With" menu can offer them.
    #[test]
    fn candidates_include_cache_entries_after_the_default() {
        let mut a = Associations::from_str_data(USER_CHOICES);
        a.merge_str(SYSTEM_CACHE);

        let names: Vec<String> = a
            .candidates_for(&mime("application/pdf"))
            .iter()
            .map(std::string::ToString::to_string)
            .collect();
        assert_eq!(
            names,
            [
                "org.gnome.Evince.desktop",
                "com.google.Chrome.desktop",
                "firefox.desktop"
            ]
        );
    }

    #[test]
    fn removed_associations_are_blocked() {
        let a = Associations::from_str_data(
            "[Added Associations]\n\
             text/plain=nvim.desktop;gedit.desktop;\n\
             [Removed Associations]\n\
             text/plain=gedit.desktop;\n",
        );
        let names: Vec<String> = a
            .candidates_for(&mime("text/plain"))
            .iter()
            .map(std::string::ToString::to_string)
            .collect();
        assert_eq!(names, ["nvim.desktop"], "gedit was explicitly removed");
    }

    #[test]
    fn duplicates_do_not_reorder_preferences() {
        let mut a = Associations::from_str_data("[MIME Cache]\ntext/html=firefox.desktop;\n");
        // A later file repeating firefox must not move it, nor duplicate it.
        a.merge_str("[MIME Cache]\ntext/html=chrome.desktop;firefox.desktop;\n");

        let names: Vec<String> = a
            .candidates_for(&mime("text/html"))
            .iter()
            .map(std::string::ToString::to_string)
            .collect();
        assert_eq!(names, ["firefox.desktop", "chrome.desktop"]);
    }

    #[test]
    fn unknown_types_have_no_handler() {
        let a = Associations::from_str_data(SYSTEM_CACHE);
        assert!(a.default_for(&mime("application/x-nonexistent")).is_none());
        assert!(
            a.candidates_for(&mime("application/x-nonexistent"))
                .is_empty()
        );
    }

    #[test]
    fn unrelated_groups_and_comments_are_ignored() {
        let a = Associations::from_str_data(
            "# a comment\n\
             [Some Other Group]\n\
             application/pdf=wrong.desktop;\n\
             [Default Applications]\n\
             application/pdf=right.desktop\n",
        );
        assert_eq!(
            a.default_for(&mime("application/pdf"))
                .map(|d| d.to_string()),
            Some("right.desktop".to_owned())
        );
    }

    #[test]
    fn malformed_lines_do_not_abort_the_parse() {
        let a = Associations::from_str_data(
            "[Default Applications]\n\
             no-equals-sign\n\
             =orphaned.desktop\n\
             text/plain=nvim.desktop\n",
        );
        assert_eq!(
            a.default_for(&mime("text/plain")).map(|d| d.to_string()),
            Some("nvim.desktop".to_owned())
        );
    }

    #[test]
    fn resolves_ids_against_explicit_roots() {
        let dir = std::env::temp_dir().join(format!("mime-assoc-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("mkdir");
        std::fs::write(dir.join("real.desktop"), b"[Desktop Entry]\n").expect("write");

        let id = DesktopId::parse("real.desktop").expect("valid");
        let found = Associations::resolve_path_in(&id, std::slice::from_ref(&dir));
        assert!(found.is_some());

        let missing = DesktopId::parse("absent.desktop").expect("valid");
        assert!(Associations::resolve_path_in(&missing, std::slice::from_ref(&dir)).is_none());

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Against the real system files, when present.
    #[test]
    fn loads_the_real_system_associations() {
        let a = Associations::load();
        if a.is_empty() {
            return;
        }
        // Any machine with a browser installed handles text/html.
        let html = a.candidates_for(&mime("text/html"));
        assert!(
            html.is_empty() || html.iter().all(|id| id.as_str().ends_with(".desktop")),
            "every resolved id must be a .desktop basename"
        );
    }
}
